      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Após incidente em offloading, recomenda-se avaliar o cenário de rompimento do mangote e identificar no HAZOP salvaguarda para baixa pressão com atuação automática de bloqueio.",
          "trechos": [
            "E8bdfd69764b991ab:1386:2082"
          ],
          "condicoes": [
            "Aplicável ao contexto de sistema de offloading e mangote associado ao incidente analisado."
          ],
          "limites": [
            "É lição aprendida e recomendação, não requisito universal.",
            "O trecho não define parâmetros de atuação nem arranjo único de proteção."
          ]
        },
        {
          "proposicao": "Recomenda-se verificar intertravamento e bloqueio automático do sistema de offloading e reavaliar as salvaguardas para alta e baixa pressão nas unidades de produção.",
          "trechos": [
            "E8bdfd69764b991ab:1386:2082",
            "E8bdfd69764b991ab:2082:2331"
          ],
          "condicoes": [
            "No âmbito das lições aprendidas do alerta da ANP para evitar ocorrências similares."
          ],
          "limites": [
            "Não é apresentado como obrigação normativa no trecho.",
            "Refere-se a sistemas de offloading; a transposição para pull-in de risers exige fonte específica."
          ]
        },
        {
          "proposicao": "A recomendação inclui revisar a necessidade de dispositivos de liberação rápida de mangote no lado do FPSO e avaliar eventual abrangência de orientação de retirada de sistemas IHTP.",
          "trechos": [
            "E8bdfd69764b991ab:2082:2331"
          ],
          "condicoes": [
            "Relacionada ao incidente envolvendo IHTP e QRF em operação de offloading."
          ],
          "limites": [
            "A própria redação indica reavaliação e necessidade de avaliação; não estabelece proibição ou solução única.",
            "O foco é mangote de offloading, não riser de produção/injeção."
          ]
        }
      ]
    },
